"""Conformance arm 1 — the platform layout survives mounting.

A compiled-member import + compute inside the mounted image: numpy must
import from the payload's site-packages (its bundled BLAS/LAPACK shared
libraries load through the VFS), and a GEMM + a reduction must return the
right numbers. Prints the import path so the log shows the VFS spelling.
"""

import os
import sys

# The conformance scripts ride inside site-packages but are run as the
# spec-17 entry (sys.path[0] is this dir) — put site-packages on the path
# from this file's OWN location, like the /bin/pydata stub.
_site = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if _site not in sys.path:
    sys.path.insert(0, _site)

import numpy as np  # noqa: E402


def main():
    print("python: %s" % sys.version.split()[0])
    print("numpy: %s" % np.__version__)
    print("numpy imported from: %s" % np.__file__)

    rng = np.arange(12, dtype=np.float64).reshape(3, 4)
    product = rng @ rng.T
    expected = np.array([[14.0, 38.0, 62.0], [38.0, 126.0, 214.0], [62.0, 214.0, 366.0]])
    if not np.allclose(product, expected):
        sys.stderr.write("arm1: GEMM mismatch:\n%s\n" % product)
        return 1
    total = float(product.sum())
    if total != 822.0:
        sys.stderr.write("arm1: reduction mismatch: %r != 822.0\n" % total)
        return 1
    print("gemm 3x4 @ 4x3 ... OK (sum %g)" % total)
    print("ARM1-OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
